// Merge ffprobe metadata + silence map + Whisper transcript + parsed brief into one edit context
const stdout = $('Media Probe').first().json.stdout || '';
const parts = stdout.split('---SILENCE---');
let probe = {};
try { probe = JSON.parse(parts[0]); } catch (e) {}
const duration = parseFloat(probe?.format?.duration || 0);

const silences = [];
for (const line of (parts[1] || '').split('\n')) {
  const s = line.match(/silence_start:\s*([\d.]+)/);
  if (s) { silences.push({ start: parseFloat(s[1]) }); continue; }
  const e = line.match(/silence_end:\s*([\d.]+)/);
  if (e && silences.length && silences[silences.length - 1].end === undefined) {
    silences[silences.length - 1].end = parseFloat(e[1]);
  }
}

const whisper = $('Whisper Transcribe').first().json;
const segments = (whisper.segments || []).map(s => ({
  start: +(+s.start).toFixed(2),
  end: +(+s.end).toFixed(2),
  text: (s.text || '').trim()
}));

const brief = $('Parse Video Brief (LLM)').first().json.message.content;

if (!duration) throw new Error('ffprobe returned no duration - is ffmpeg installed on the n8n host?');
if (!segments.length) throw new Error('Whisper returned no segments - check the audio extraction step');

return [{ json: { duration, silences, segments, brief } }];

// Deterministic EDL validation + auto-snap to silence boundaries (the Keyword Validator of this pipeline)
const runs = $json.runs || 0;
let raw = $json.edl_raw ?? $json.message?.content;
let edl = null;
if (typeof raw === 'object' && raw !== null) edl = raw;
else {
  try {
    edl = JSON.parse(String(raw).replace(/^[\s\S]*?```json/i, '').replace(/```[\s\S]*$/, '').trim());
  } catch (e) { edl = null; }
}

const ctx = $('Assemble Edit Context').first().json;
const issues = [];
if (!edl || !Array.isArray(edl.clips) || edl.clips.length === 0) {
  issues.push('EDL is missing a non-empty clips array');
}

let clips = (edl?.clips || [])
  .map(c => ({
    start: Math.max(0, +c.start || 0),
    end: Math.min(ctx.duration, +c.end || 0),
    label: String(c.label || 'clip').replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 40),
    reason: c.reason || ''
  }))
  .filter(c => c.end > c.start);

// Auto-snap boundaries to the nearest silence edge within 0.6s so cuts never chop words
const bounds = [];
for (const s of ctx.silences) {
  if (s.start !== undefined) bounds.push(s.start);
  if (s.end !== undefined) bounds.push(s.end);
}
const snap = t => {
  let best = t, d = 0.6;
  for (const b of bounds) { const dd = Math.abs(b - t); if (dd < d) { d = dd; best = b; } }
  return +best.toFixed(2);
};
clips = clips.map(c => ({ ...c, start: snap(c.start), end: snap(c.end) })).filter(c => c.end - c.start >= 3);

clips.sort((a, b) => a.start - b.start);
for (let i = 1; i < clips.length; i++) {
  if (clips[i].start < clips[i - 1].end) issues.push(`Clips ${i - 1} and ${i} overlap after snapping`);
}

const target = +ctx.brief?.target_clip_seconds || 60;
clips.forEach((c, i) => {
  const len = c.end - c.start;
  if (len > target * 1.5) issues.push(`Clip ${i} is ${len.toFixed(0)}s - far over the ${target}s target`);
  if (len < target * 0.4) issues.push(`Clip ${i} is only ${len.toFixed(0)}s - too short for the ${target}s target`);
});

const wanted = +ctx.brief?.clips_count || 3;
if (clips.length < wanted) issues.push(`Brief asked for ${wanted} clips, usable EDL has ${clips.length}`);

return [{ json: {
  passed: issues.length === 0,
  issues,
  runs,
  clips,
  video_title: edl?.video_title || '',
  video_description: edl?.video_description || ''
} }];

