return [{ json: {
  edl_raw: $json.message.content,
  runs: ($('EDL Validator & Auto-Snap').first().json.runs || 0) + 1
} }];

// Build one render job per clip: re-timed SRT captions + full ffmpeg command. All deterministic, $0.
const v = $('EDL Validator & Auto-Snap').first().json;
const ctx = $('Assemble Edit Context').first().json;
const execId = $execution.id;
const src = `/tmp/vp_${execId}_source.mp4`;
const aspect = ctx.brief?.aspect_ratio || '9:16';
const burn = ctx.brief?.captions !== false;

const esc = t => t.replace(/\n/g, ' ').trim();
const fmtT = t => {
  const ms = String(Math.round((t % 1) * 1000)).padStart(3, '0');
  const s = Math.floor(t);
  const hh = String(Math.floor(s / 3600)).padStart(2, '0');
  const mm = String(Math.floor((s % 3600) / 60)).padStart(2, '0');
  const ss = String(s % 60).padStart(2, '0');
  return `${hh}:${mm}:${ss},${ms}`;
};

const out = [];
for (let i = 0; i < v.clips.length; i++) {
  const c = v.clips[i];
  // Re-time transcript segments to clip-local time for the burned captions
  const segs = ctx.segments.filter(s => s.end > c.start && s.start < c.end);
  let srt = '';
  let n = 1;
  for (const s of segs) {
    const a = Math.max(0, s.start - c.start);
    const b = Math.min(c.end - c.start, s.end - c.start);
    if (b <= a) continue;
    srt += `${n++}\n${fmtT(a)} --> ${fmtT(b)}\n${esc(s.text)}\n\n`;
  }
  const srtPath = `/tmp/vp_${execId}_clip_${i}.srt`;
  const outPath = `/tmp/vp_${execId}_clip_${i}.mp4`;
  let vf = aspect === '9:16' ? 'crop=ih*9/16:ih,scale=1080:1920'
         : aspect === '1:1' ? 'crop=ih:ih,scale=1080:1080'
         : 'scale=-2:1080';
  if (burn && srt) vf += `,subtitles=${srtPath}`;
  const cmd = `ffmpeg -y -ss ${c.start} -to ${c.end} -i ${src} -vf "${vf}" -af loudnorm=I=-16:TP=-1.5:LRA=11 -c:v libx264 -preset veryfast -crf 20 -c:a aac -b:a 128k ${outPath}`;
  out.push({
    json: {
      index: i,
      label: c.label,
      start: c.start,
      end: c.end,
      reason: c.reason,
      target_len: +(c.end - c.start).toFixed(2),
      srt_path: srtPath,
      out_path: outPath,
      ffmpeg_cmd: cmd
    },
    binary: {
      data: await this.helpers.prepareBinaryData(Buffer.from(srt || ' ', 'utf8'), `clip_${i}.srt`)
    }
  });
}
return out;

// Deterministic output QA: duration within 1.5s of the EDL target, non-empty file
let probe = {};
try { probe = JSON.parse($json.stdout || '{}'); } catch (e) {}
const job = $('Prepare Render Jobs').item.json;
const dur = parseFloat(probe?.format?.duration || 0);
const size = parseInt(probe?.format?.size || 0);
const ok = dur > 0 && size > 0 && Math.abs(dur - job.target_len) <= 1.5;
return { json: {
  ...job,
  rendered_duration: +dur.toFixed(2),
  qa_passed: ok,
  qa_issue: ok ? '' : `Expected ~${job.target_len}s, got ${dur.toFixed(2)}s (size ${size} bytes)`
} };

// Aggregate everything into the edit report - the video analog of Skywide's verified_claims payload
const qa = $('QA Check').all().map(i => i.json);
const uploads = $input.all().map(i => i.json);
const v = $('EDL Validator & Auto-Snap').first().json;
const body = $('Video Webhook').first().json.body;
const folderId = $('Create Project Folder').first().json.id;

const clips = qa.map((q, i) => ({
  label: q.label,
  source_start: q.start,
  source_end: q.end,
  duration: q.rendered_duration,
  why_this_clip: q.reason,
  qa_passed: q.qa_passed,
  qa_issue: q.qa_issue,
  drive_link: uploads[i]?.id ? `https://drive.google.com/file/d/${uploads[i].id}/view` : ''
}));

return [{ json: {
  request_id: body.request_id || '',
  run_id: body.run_id || '',
  folder_url: `https://drive.google.com/drive/folders/${folderId}`,
  video_title: v.video_title,
  video_description: v.video_description,
  edl_validation_issues: v.issues,
  edl_retries_used: v.runs,
  clips
} }];
